class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple):
        super().__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))
        self._ctas_per_row = 8
        self._block_size = 1024
        self._ws_batch = None
        self._ws_device = None
        self._sum_buf = None
        self._sumsq_buf = None
        self._counter_buf = None
        self._ready_buf = None
        self._mean_buf = None
        self._invstd_buf = None
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output = torch.empty_like(x)
        batch_size = x.shape[0]
        device = x.device
        if self._ws_batch != batch_size or self._ws_device != device:
            self._sum_buf = torch.zeros(batch_size, dtype=torch.float64, device=device)
            self._sumsq_buf = torch.zeros(batch_size, dtype=torch.float64, device=device)
            self._counter_buf = torch.zeros(batch_size, dtype=torch.int32, device=device)
            self._ready_buf = torch.zeros(batch_size, dtype=torch.int32, device=device)
            self._mean_buf = torch.zeros(batch_size, dtype=torch.float32, device=device)
            self._invstd_buf = torch.zeros(batch_size, dtype=torch.float32, device=device)
            self._ws_batch = batch_size
            self._ws_device = device
        else:
            self._sum_buf.zero_()
            self._sumsq_buf.zero_()
            self._counter_buf.zero_()
            self._ready_buf.zero_()
        module = _get_ptx_module()
        module.launch(
            "layernorm_kernel",
            grid=(batch_size * self._ctas_per_row, 1, 1),
            block=(self._block_size, 1, 1),
            arguments=[
                x, output, self.weight, self.bias,
                self._sum_buf, self._sumsq_buf, self._counter_buf, self._ready_buf,
                self._mean_buf, self._invstd_buf,
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

